// Real route and real SQLite transactions, with only D1 transport/auth/entropy adapted
// in memory. No preview, credentials, existing DB or production state is touched.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs/promises';
import {DatabaseSync} from 'node:sqlite';
import {fileURLToPath,pathToFileURL} from 'node:url';
import ts from 'typescript';
import {makeMon,moves,effectiveness} from '../lib/game.mjs';
import {stableTeraType,TERA_TYPES} from '../lib/tera-type.mjs';
import {configure} from '../lib/pokemon-config.mjs';
import {createCombat,playCpu} from '../lib/party-battle.mjs';
import {Battle} from '@pkmn/sim';
import {expToNext,gainExperience,victoryExperience} from '../lib/growth.mjs';
import {activeRoyaleZones} from '../lib/cloud-adventure/adventure-royale-zones.mjs';
import {canariBattleExperience} from '../lib/cloud-adventure/adventure-canari.mjs';
import {fieldPath,fieldMap,findTile,storeAdventurePosition} from '../lib/cloud-adventure/adventure-world.mjs';
import {TRAINERS} from '../lib/campaign.mjs';
import {ZONE20_ALPHA} from '../lib/cloud-adventure/adventure-mission42.mjs';
import lumioseDex from '../data/lumiose-dex.json' with {type:'json'};
import {RESEARCH_TYPES,researchSummary,researchItemReward} from '../lib/cloud-adventure/adventure-research.mjs';

const root=fileURLToPath(new URL('../',import.meta.url)),sql=new DatabaseSync(':memory:');
for(const name of (await fs.readdir(new URL('../drizzle/',import.meta.url))).filter(n=>/^\d.*\.sql$/.test(n)).sort())sql.exec(await fs.readFile(new URL('../drizzle/'+name,import.meta.url),'utf8'));
function prepare(query,args=[]){return {bind(...values){return prepare(query,values);},async first(){return sql.prepare(query).get(...args)||null;},async all(){return {results:sql.prepare(query).all(...args)};},async run(){if(/^\s*SELECT\b/i.test(query))return {results:sql.prepare(query).all(...args),meta:{changes:0}};const r=sql.prepare(query).run(...args);return {meta:{changes:Number(r.changes)}};}};}
globalThis.__adventureEnv={DB:{prepare,async batch(statements){sql.exec('BEGIN');try{const result=[];for(const s of statements)result.push(await s.run());sql.exec('COMMIT');return result;}catch(e){sql.exec('ROLLBACK');throw e;}}}};
globalThis.__adventureUser={userId:'adventure-qa',displayName:'탐험테스트'};globalThis.__adventureRandom=()=>.999;
async function loadTS(relative){
 let source=await fs.readFile(new URL('../'+relative,import.meta.url),'utf8');
 source=source.replace(/import\s*\{\s*env\s*\}\s*from\s*['"]cloudflare:workers['"];?/g,'const env=globalThis.__adventureEnv;');
 source=source.replace(/import\s*\{getChatGPTUser\}\s*from\s*['"]@\/app\/chatgpt-auth['"];?/g,'const getChatGPTUser=async()=>globalThis.__adventureUser;');
 source=source.replace("const random=()=>crypto.getRandomValues(new Uint32Array(1))[0]/4294967296;","const random=()=>globalThis.__adventureRandom();");
 source=source.replace("import {evolutionOptions,evolutionContext,gameTime} from '@/lib/evolution.mjs';","import {evolutionOptions,evolutionContext,gameTime as realGameTime} from '@/lib/evolution.mjs';const gameTime=(now,offset=0)=>{const t=globalThis.__adventureTime;if(!t)return realGameTime(now,offset);if(!offset)return t;const hour=(t.hour+offset)%24;return {...t,hour,period:hour>=6&&hour<18?'day':'night',dusk:hour>=17&&hour<19};};");
 const inventoryURL=relative==='lib/cloud-adventure/route.ts'?await loadTS('lib/inventory.ts'):null;
 const battleLockURL=relative==='app/api/trades/route.ts'?await loadTS('lib/battle-lock.ts'):null;
 source=source.replace(/from\s*(['"])(@\/[^'"]+|\.\.?\/[^'"]+)\1/g,(_,quote,specifier)=>{
  if(specifier==='@/lib/inventory')return `from '${inventoryURL}'`;
  if(specifier==='@/lib/battle-lock')return `from '${battleLockURL}'`;
  const url=specifier.startsWith('@/')?pathToFileURL(root+specifier.slice(2)):new URL(specifier,new URL('../'+relative,import.meta.url));return `from '${url.href}'`;
 });
 const emitted=ts.transpileModule(source,{compilerOptions:{target:ts.ScriptTarget.ES2022,module:ts.ModuleKind.ESNext}}).outputText;
 return 'data:text/javascript;base64,'+Buffer.from(emitted).toString('base64');
}
const route=await import(await loadTS('lib/cloud-adventure/route.ts'));
let state;
async function get(){const r=await route.GET(new Request('http://adventure.test/api/world'));assert.equal(r.status,200);return state=await r.json();}
async function call(action,extra={},expected=200){const r=await route.POST(new Request('http://adventure.test/api/world',{method:'POST',headers:{'content-type':'application/json',origin:'http://adventure.test'},body:JSON.stringify({action,revision:state?.revision,...extra})}));const d=await r.json();assert.equal(r.status,expected,`${action}: ${JSON.stringify(d)}`);if(expected===200)state=d;return d;}
function rawWorld(){return JSON.parse(sql.prepare('SELECT state FROM worlds WHERE user_id=?').get(globalThis.__adventureUser.userId).state);}
function seedWorld(patch){const w={...rawWorld(),...patch};sql.prepare('UPDATE worlds SET state=?,revision=revision+1 WHERE user_id=?').run(JSON.stringify(w),globalThis.__adventureUser.userId);}
function rawMon(id){return JSON.parse(sql.prepare('SELECT data FROM pokemon_box WHERE id=?').get(id).data);}
function seedMon(id,p){sql.prepare('UPDATE pokemon_box SET species_id=?,data=? WHERE id=?').run(p.id,JSON.stringify(p),id);}
async function walkTo(tileOrTarget){if(tileOrTarget==='W'&&state.world.district==='lumiose'&&!state.world.interior){await walkTo({x:8,y:14});await call('move',{direction:'down'});assert.equal(state.world.district,'lumiose-zone1');return;}const target=typeof tileOrTarget==='string'?findTile(state.world.map,tileOrTarget):tileOrTarget;assert.ok(target);const gate=['E','W'].includes(typeof tileOrTarget==='string'?tileOrTarget:'');const origin=[state.world.area,state.world.district,state.world.interior,!!state.world.expedition];for(let n=0;n<100;n++){if(gate&&[state.world.area,state.world.district,state.world.interior,!!state.world.expedition].some((v,i)=>v!==origin[i]))return;if(!gate&&state.world.x===target.x&&state.world.y===target.y)return;const path=fieldPath(state.world.map,state.world,target);assert.ok(path.length,'target remains reachable');await call('move',{path:path.slice(0,8)});assert.equal(state.battle,null);}assert.fail('movement did not reach target');}
async function travelToZone2(){assert.equal(state.world.district,'lumiose');await walkTo('h');await call('enterRooftop');await walkTo('W');assert.equal(state.world.district,'lumiose-zone2');}
function testBattleMove(q,p,foe){return q.moves.filter(m=>!m.disabled&&m.pp>0).map(m=>({m,score:(moves[m.name]?.power||0)*effectiveness(moves[m.name]?.type,foe.currentTypes||foe.types)*(p.types.includes(moves[m.name]?.type)?1.5:1)})).sort((a,b)=>b.score-a.score)[0].m.name;}
async function battle({resolve=true}={}){let turns=0;while(state.battle||state.world.adventureCatchWindow){assert.ok(turns++<180,'battle finishes');if(state.world.adventureCatchWindow){await call('skipCatchWindow');assert.equal(state.battle,null);continue;}const b=state.battle,q=b.requests[0],p=b.teams[0][b.active[0]],foe=b.teams[1][b.active[1]];let command;if(Array.isArray(q.actors)){const actor=q.actors[0];if(actor.kind==='switch')command={type:'turn',actions:[{actor:actor.slot,type:'switch',slot:actor.switches.sort((a,b)=>b.hp-a.hp)[0].slot}]};else{const name=testBattleMove(actor,p,foe),move=actor.moves.find(m=>m.name===name),target=move.targets?.find(t=>t.side===1)?.target;command={type:'turn',actions:[{actor:actor.slot,type:'move',move:move.id,...(target?{target}:{})}]};}}else command=q.kind==='switch'?{type:'switch',slot:q.switches.sort((a,b)=>b.hp-a.hp)[0].slot}:{type:'move',move:testBattleMove(q,p,foe)};await call('battle',{command});if(!state.battle&&!state.world.adventureCatchWindow){assert.equal(state.battleResult?.ended,true);assert.ok(Array.isArray(state.battleResult.events));assert.equal(rawWorld().combat,null);}}if(resolve)while(state.world.adventurePendingMoves?.length)await call('resolveAdventureMove',{slot:null});return turns;}

test('battle fixture avoids moves blocked by current Tera type',()=>{const q={moves:[{name:'사이코브레이크',pp:10},{name:'파동탄',pp:10}]},p={types:['에스퍼']},foe={types:['고스트'],currentTypes:['악']};assert.equal(testBattleMove(q,p,foe),'파동탄');assert.equal(testBattleMove(q,p,{types:['고스트'],currentTypes:['고스트']}),'사이코브레이크');});

test('Mission 36 rooftop visit persists and legacy tower progress remains available',async()=>{
 const previousUser=globalThis.__adventureUser;globalThis.__adventureUser={userId:'mission36-roof-qa',displayName:'옥상테스트'};
 try{
  await get();await call('start',{species:1});const team=[...state.world.teamIds],wallet=structuredClone(state.wallet);
  seedWorld(storeAdventurePosition({...rawWorld(),area:3,district:'lumiose-centrico-route',interior:null,x:15,y:6,facing:'up',zaRoyaleRank:'A',zaMission35Stage:7,zaMission35Won:true},state.revision+1));await get();
  await call('mission35Reward');assert.equal(state.world.zaMission36RoofRequired,true);await call('mission36Tower',{},409);
  seedWorld(storeAdventurePosition({...rawWorld(),district:'lumiose',interior:'hotel2f',x:11,y:12,facing:'up'},state.revision+1));await get();await walkTo('i');await call('hotelLiftRoof');await get();
  await walkTo({x:11,y:8});await call('face',{direction:'up'});assert.equal(state.world.interaction.action,'mission36Roof');await call('mission36Roof');await get();assert.equal(state.world.zaMission36RoofSeen,true);await call('mission36Roof',{},409);
  seedWorld(storeAdventurePosition({...rawWorld(),district:'lumiose-centrico-route',interior:null,x:15,y:6,facing:'up'},state.revision+1));await get();await call('mission36Tower');assert.equal(state.world.zaMission36Stage,1);assert.deepEqual(state.world.teamIds,team);assert.deepEqual(state.wallet,wallet);
  seedWorld(storeAdventurePosition({...rawWorld(),district:'lumiose-centrico-route',interior:null,x:15,y:6,facing:'up',zaMission36Stage:0,zaMission36RoofRequired:false,zaMission36RoofSeen:false},state.revision+1));await get();await call('mission36Tower');assert.equal(state.world.zaMission36Stage,1);
 }finally{globalThis.__adventureUser=previousUser;}
});

test('Mission 36 rival defeat continues the story without victory rewards',async()=>{
 const previousUser=globalThis.__adventureUser;globalThis.__adventureUser={userId:'mission36-defeat-qa',displayName:'동료배틀테스트'};
 try{
  await get();await call('start',{species:1});const id=state.world.activeId,team=[...state.world.teamIds],coins=state.wallet.coins;
  seedWorld(storeAdventurePosition({...rawWorld(),area:3,district:'lumiose-centrico-route',interior:null,x:15,y:6,facing:'up',zaMission36Started:true,zaMission36Stage:1,zaMission10Starter:'grass'},state.revision+1));await get();
  await call('mission36Rival');await call('forfeit');assert.equal(state.world.zaMission36Stage,1);assert.equal(state.wallet.coins,coins);
  seedWorld(storeAdventurePosition({...rawWorld(),district:'lumiose-centrico-route',interior:null,x:15,y:6,facing:'up'},state.revision+1));await get();await call('mission36Rival');
  for(let turns=0;state.battle;turns++){assert.ok(turns<20);const req=state.battle.requests[0];assert.equal(req.kind,'move');const move=req.moves.find(m=>!m.disabled&&m.pp>0);assert.ok(move);await call('battle',{command:{type:'move',move:move.name}});}
  assert.equal(state.battleResult.winner,1);assert.equal(state.world.zaMission36Stage,2);assert.equal(state.wallet.coins,coins);assert.deepEqual(state.world.teamIds,team);await get();assert.equal(state.world.zaMission36Stage,2);await call('mission36Vinnie');assert.equal(state.world.zaMission37Started,true);await call('mission36Vinnie',{},409);
 }finally{globalThis.__adventureUser=previousUser;}
});

